mapper.select:
SELECT audit_logs.id, audit_logs.action, audit_logs.entity_type AS entityType, audit_logs.entity_id AS entityId,
       audit_logs.entity_name AS entityName, audit_logs.actor_name AS actorName, audit_logs.description, audit_logs.created_at AS createdAt
FROM audit_logs WHERE audit_logs.store_id=#{storeId}
ORDER BY audit_logs.created_at DESC, audit_logs.id DESC LIMIT #{limit} OFFSET #{offset}
